 BattleActorServices memory(){BattleActorServices m;m.user=this;m.memory.user=this;m.memory.word=[](void* p,uint32_t at){return static_cast<Fixture*>(p)->words[at];};m.memory.storeWord=[](void* p,uint32_t at,uint32_t v){auto& f=*static_cast<Fixture*>(p);f.words[at]=v;if(f.itemMutation && at==M+0x94)f.words[f.itemMutation+0x24]=0x81000;f.stores.emplace_back(at,v);};m.memory.half=[](void* p,uint32_t at){return static_cast<Fixture*>(p)->halves[at];};m.memory.storeHalf=[](void* p,uint32_t at,uint16_t v){auto& f=*static_cast<Fixture*>(p);f.halves[at]=v;f.stores.emplace_back(at,v);};m.byte=[](void* p,uint32_t at){return static_cast<Fixture*>(p)->bytes[at];};return m;}
