 s.unit=[](void*,uint32_t b,int32_t id){assert(b==B && id==1);return U;};s.pouch=[](void*){return P;};s.cursor=[](void* p,uint32_t m,uint32_t,uint32_t out){assert(m==M);static_cast<Fixture*>(p)->words[out]=C;};
