 Fixture dummy;dummy.words[0x80363e60]=99;assert(dummy.build(2)==1 && dummy.words[Fixture::M+0x80]==0x80363e60 && dummy.words[Fixture::M+0x90]==0 && dummy.halves[Fixture::M+0x8c]==362);bool minus=false,zero=false;for(auto v:dummy.stores)if(v.first==Fixture::M+0x90){if(v.second==0xffffffff)minus=true;else if(minus && !v.second)zero=true;}assert(zero);
 Fixture inventory;inventory.halves[Fixture::P+0x192]=100;const auto entry=0x803108a8+4000;inventory.halves[entry+0x10]=2;inventory.words[entry+4]=77;inventory.halves[entry+0x20]=250;assert(inventory.build(2)==1 && inventory.words[Fixture::M+0x80]==0x80365488 && inventory.words[Fixture::M+0x88]==78);size_t nameAt=0,iconAt=0;for(size_t i=0;i<inventory.stores.size();++i){if(inventory.stores[i].first==Fixture::M+0x88)nameAt=i;if(inventory.stores[i].first==Fixture::M+0x8c)iconAt=i;}assert(nameAt<iconAt);
 Fixture special;special.halves[Fixture::P+0x8c]=5;special.words[0x80355ca8]=0x80000;special.halves[0x80004]=333;assert(special.build(4)==1 && special.halves[Fixture::M+0x8c]==333);
 Fixture party;party.words[Fixture::U+0x18]=0x80000;party.words[0x80000]=1;party.words[0x80004]=44;assert(party.build(6)==3 && party.words[Fixture::C+8]==3);party.partyReady=false;assert(!party.build(6).has_value());
 Fixture mutated;mutated.bytes[Fixture::P+0x98]=1;mutated.messageMutation=5;assert(mutated.build(0)==6 && mutated.words[Fixture::M+28*5+0x88]==1 && mutated.words[Fixture::C+8]==6); // Visible private count changes are retained.
 Fixture negative;negative.bytes[Fixture::P+0x98]=1;negative.words[Fixture::C]=uint32_t(-2);negative.words[Fixture::C+4]=uint32_t(-1);assert(negative.build(0)==1 && negative.words[Fixture::C]==uint32_t(-2) && negative.words[Fixture::C+4]==uint32_t(-1));
 Fixture live;auto liveServices=live.services();live.bytes[Fixture::P+0x98]=3;liveServices.jumpIcon=[](void* p){auto& f=*static_cast<Fixture*>(p);f.bytes[Fixture::P+0x98]=1;return uint16_t(165);};assert(makePackedBattleWeaponTable(Fixture::B,0,liveServices)==1);
 Fixture captured;captured.halves[Fixture::P+0x8c]=5;captured.words[0x80355ca8]=0x80000;captured.words[0x80355cb0]=0x80020;auto capturedServices=captured.services();capturedServices.message=[](void* p,uint32_t)->uint32_t{static_cast<Fixture*>(p)->halves[Fixture::P+0x8c]=0;return uint32_t(1);};assert(makePackedBattleWeaponTable(Fixture::B,4,capturedServices)==2);
 Fixture signedItem;signedItem.halves[Fixture::P+0x192]=65535;signedItem.halves[0x803108a8-40+0x10]=2;assert(signedItem.build(2)==1 && signedItem.words[Fixture::M+0x94]==0xffffffff);
 Fixture zeroMenu;zeroMenu.words[uint32_t(-0x171c)+0x420]=77;zeroMenu.words[Fixture::N]=123;auto zeroServices=zeroMenu.services();zeroServices.unit=[](void*,uint32_t b,int32_t id){assert(b==uint32_t(-0x171c) && id==77);return Fixture::U;};assert(makePackedBattleWeaponTable(uint32_t(-0x171c),0,zeroServices)==0 && zeroMenu.stores.empty() && zeroMenu.words[Fixture::N]==123);
 Fixture eligibility;eligibility.words[Fixture::C+8]=3;eligibility.words[Fixture::M+0x80]=0x80000;eligibility.words[Fixture::M+0x80+28]=0x80001;BattleWeaponEligibilityServices e;e.memory=eligibility.memory();e.user=&eligibility;e.cursorSlot=Fixture::CS;e.unit=eligibility.services().unit;e.cursor=eligibility.services().cursor;e.targetCount=[](void* p,uint32_t,uint32_t,uint32_t w)->std::optional<int32_t>{auto& f=*static_cast<Fixture*>(p);f.words[Fixture::C+8]=0;return w==0x80000?1:-1;};assert(updatePackedBattleWeaponTable(Fixture::B,4,e));assert(eligibility.words[Fixture::M+0x84]==1 && eligibility.words[Fixture::M+28+0x98]==2 && eligibility.words[Fixture::M+56+0x84]==0);
 Fixture targets;BattleWeaponTargetCountServices t;t.memory=targets.memory();t.user=&targets;t.privateBuffer=0x90000;t.cost=[](void*,uint32_t,uint32_t){return -1;};t.enemyBelong=[](void*,uint32_t){return 256;};t.sample=[](void* p,uint32_t buffer,uint32_t,int32_t actor,int32_t belong,uint32_t,uint32_t,int32_t dir){auto& f=*static_cast<Fixture*>(p);assert(buffer==0x90000 && actor==1 && belong==0 && dir==-7);f.bytes[buffer+0xa6c]=255;return true;};targets.words[Fixture::U]=1;targets.words[0x80000+0xb0]=1;targets.bytes[Fixture::B+256*8+0xa]=7;assert(packedWeaponTargetCount(Fixture::B,Fixture::U,0,t)==0 && packedWeaponTargetCount(Fixture::B,Fixture::U,0x80000,t)==-1);t.cost=[](void*,uint32_t,uint32_t){return 0;};assert(packedWeaponTargetCount(Fixture::B,Fixture::U,0x80000,t)==-1);
